# -*- coding: utf-8 -*-
"""逐问解读（下）：问153–196，蒙恩之道与祷告。"""

from unit import U

UNITS = [

U("u35", "问153–155", "出路：蒙恩之道，与圣道如何生效",
  [(153, "既然我们干犯了律法，神要求我们作什么，才可逃避祂的忿怒与咒诅？", "三样：<b>向神悔改</b>，<b>信靠我们的主耶稣基督</b>，以及<b>殷勤使用基督藉以把祂中保之益处传给我们的外在方法</b>。"),
   (154, "那些外在的方法是什么？", "基督藉以把中保之益处传给祂教会的<b>外在而普通</b>的方法，就是祂一切的典章；<em>尤其是圣道、圣礼与祷告</em>——这一切都被作成对选民有效，以致他们得救。"),
   (155, "圣道如何被作成有效以致人得救？", "神的灵使人读经、<b>尤其是听人传讲圣道</b>，成为有效的方法：光照人、使人知罪、使人自卑；<em>把他们从自己里面赶出来，吸引他们归向基督</em>；使他们与基督的形像相符，制伏他们归服祂的旨意；在试探与败坏中加力给他们；在恩典中建立他们，藉信心把他们的心坚固在圣洁与安慰中，以致得救。")],
  core="问 153 的次序是全篇的转折：律法把人逼到尽头（问149–152），出路不是「更努力守法」，而是<b>悔改、信心、殷勤使用蒙恩之道</b>。前两样是回应，第三样是管道。请注意大要理没有把话停在「信就够了」——它立刻具体地指出<em>信心在哪里被喂养、被坚固</em>。",
  why="「<b>外在而普通</b>」（outward and ordinary）两个形容词都有针对性。「外在」针对当时寻求内在之光与直接启示的激进派：<em>神所定的管道是可见、可用、公共的</em>。「普通」针对另一头的推论：这不是说神不能例外行事，而是说<em>人不可绕过管道自订捷径</em>。",
  cont="海德堡问 65 给出同一个神学的另一种表达：「<b>信心既然是我们分享基督与祂一切恩惠的唯一途径，这信心从哪里来？</b>答：从圣灵来；祂藉着<em>圣福音的传讲</em>在我们心中作成信心，又藉着<em>圣礼的使用</em>坚固这信心。」——圣道生成信心，圣礼坚固信心。<b>这个「生成／坚固」的分工，比威敏的并列更清楚，建议合并记忆。</b>",
  view="问 155 的「<b>尤其是听人传讲</b>」（but especially the preaching）是改革宗敬拜观的一句重话。它并不贬低私下读经（问 156 立刻要求人人读经），而是把<em>公开传讲</em>置于首位——因为讲道是神所设立的、带着职分权柄的宣告，不只是信息的传递。",
  app="若你在属灵上枯干，问 153–155 给出的第一个诊断问题不是「我的信心怎么了」，而是「我有没有殷勤使用管道」。这一问把注意力从内省转向了神所设立的外在方法上——这常常是出路。",
  keys="徒20:21　箴8:33–34　徒2:41–42　尼8:8　林前14:24–25　徒26:18　帖前1:5–6　罗15:4"),

U("u36", "问156–160", "圣道：谁读、怎么读、谁讲、怎么讲、怎么听",
  [(156, "神的道当由所有人来读吗？", "虽然不是所有人都可以<em>在会众面前公开诵读</em>圣经，但<b>各样的人都有本分</b>自己私下读、并与家人一同读；为此目的，<b>圣经当从原文译成通用的语言</b>。"),
   (157, "神的道当如何读？", "以崇高敬虔的看重来读；<b>确信它们正是神的话，且唯有祂能使我们明白</b>；带着渴望去认识、相信并顺服其中所启示的神的旨意；殷勤而专注于它的内容与主旨；并以默想、应用、克己与祷告来读。"),
   (158, "神的道当由谁来传讲？", "唯有那些<b>恩赐足够，并按正当程序被认可、被呼召</b>担任此职的人。"),
   (159, "受召者当如何传讲？", "传<b>纯正的道理</b>；<em>殷勤地</em>，无论得时不得时；<em>浅白地</em>，不用人智慧委婉的言语，乃用圣灵与大能的明证；<em>忠心地</em>，把神全备的旨意都传明；<em>智慧地</em>，切合听者的需要与领受力；<em>热切地</em>，带着对神与对祂百姓灵魂的挚爱；<em>真诚地</em>，以祂的荣耀、以听者的归正、造就与得救为目标。"),
   (160, "听道的人当尽什么本分？", "以<b>殷勤、预备与祷告</b>来听；<b>用圣经察验所听的</b>；以信心、爱心、温柔与乐意的心领受真理，如同领受神的话；默想并彼此谈论；<em>把它藏在心里，并在生活中结出果子来</em>。")],
  core="这五问把「圣道」拆成了一条完整的链：<b>翻译 → 私下读 → 家庭读 → 按立的传讲 → 会众的领受</b>。每一环都有具体的本分，每一环都可能断裂。<em>大要理不把讲道当成单向的输出，而当成一件需要讲者与听者共同完成的事</em>——问 159 与问 160 的对称结构就是这个意思。",
  why="问 156 的「圣经当译成通用语言」在当时是一句战斗性的宣告——它直接针对罗马教长期以拉丁文垄断圣经、限制平信徒读经的作法。<b>这一句是宗教改革的成果被写进信条</b>。同时「不是所有人都可公开诵读」则维护了公共敬拜中职分的秩序。",
  cont="比利时信条第 7 条论圣经的完备，第 3 条论圣经的默示，与问 157 的「确信它们正是神的话」对应。<b>但在「如何听道」这一点上，欧陆三项合一信条没有对应条目——这是大要理的一项独特贡献。</b>问 160 的五个动词（殷勤听、察验、领受、默想、结果）至今仍是最实用的听道指南。",
  view="问 159 的六个副词（殷勤、浅白、忠心、智慧、热切、真诚）是改革宗讲道学的浓缩。其中「<b>浅白地，不用人智慧委婉的言语</b>」在当时针对的是流行的宫廷式华丽讲章（metaphysical preaching）。清教徒的「浅白讲道」（plain style）不是文采差，而是<em>刻意的神学选择</em>：讲章的力量应来自圣灵与真理，不来自修辞技巧。",
  app="问 160 的「<b>用圣经察验所听的</b>」（徒17:11）给了会众一项本分，也给了讲台一道护栏。健康的教会里，听道者不是被动的接收器；他们带着圣经来，也带着圣经回去核对。",
  keys="申17:19　约5:39　赛66:2　彼后1:19–21　提后2:15　提前3:2,6　多1:9　提后4:2　林前2:4　徒20:27　徒17:11　来4:2　雅1:21–25"),

U("u37", "问161–164", "圣礼总论：它凭什么有效，它是什么，有几个",
  [(161, "圣礼如何成为有效的得救方法？", "<b>不是凭它们自身的任何能力</b>，也不是凭施行者的敬虔或意图所生的功效；<em>乃唯独藉着圣灵的运行，与设立它们之基督的祝福</em>。"),
   (162, "圣礼是什么？", "圣礼是基督在祂教会中所设立的圣洁典章，为要向那些<b>在恩典之约之内的人</b>，<em>表明、印证并施予</em>祂中保之职的益处；坚固并增加他们的信心与一切其他恩典；约束他们顺服；见证并培养他们彼此的爱与相通；并把他们与外邦人分别出来。"),
   (163, "圣礼有哪几部分？", "两部分：一是<b>外在可感的记号</b>，按基督自己的指定而用；二是<b>内在属灵的恩典</b>，由此记号所表明。"),
   (164, "基督在新约之下为教会设立了几个圣礼？", "<b>只有两个</b>：洗礼与主餐。")],
  core="问 161 是整个圣礼论的地基，它用一句话同时否定了两个方向：<b>否定「事效论」</b>（<span class=\"lt\">ex opere operato</span>，圣礼因执行本身就生效），<b>也否定「人效论」</b>（圣礼的效力取决于施行者的敬虔）。效力全在<em>圣灵的运行与基督的祝福</em>。这意味着：一位不虔诚的牧师所施的洗礼仍然有效，因为有效性不在他身上。",
  why="问 162 的三个动词<b>「表明、印证并施予」</b>（signify, seal, exhibit）是精心选择的。「表明」拒绝了纯象征说（茨温利式的「只是记号」）；「施予」拒绝了空洞的纪念说；而「印证」保证了圣礼不制造恩典，只印证并加强已有的应许。<em>三个动词一起，才是改革宗的立场。</em>",
  cont="海德堡问 66 的定义与此几乎同义：「圣礼是可见的圣洁记号与印记，由神所设立，<b>为要藉着使用它们，更充分地向我们宣明、并印证福音的应许</b>：就是因基督在十架上一次完成的献祭，祂白白赐给我们赦罪与永生。」比利时信条第 33 条同样强调「神加上这些可见的记号，是因着我们的粗钝与软弱」——<em>圣礼的存在本身就是神对人有限性的体恤</em>。这个牧养性的解释，是欧陆信条的一贯语气。",
  view="「只有两个」（问164）针对罗马教的七圣礼。判准是：<b>必须由基督亲自设立，并普遍地命定给教会</b>。按这个判准，坚振、告解、婚配、圣秩、终傅都不合格——婚姻是创造的设立而非救赎的记号，按立是职分而非圣礼。",
  app="问 161 给出一个实际的安慰：你的洗礼有效与否，不取决于当日主持的牧师属灵状况如何，也不取决于你当时的感受如何。它的效力挂在基督身上。",
  keys="彼前3:21　太3:11　林前3:6–7　罗4:11　林前10:16　创17:7,10　罗6:3–4　太28:19　林前11:23–26"),

U("u38", "问165–167", "洗礼：印记、对象，与那个「被严重忽略的本分」",
  [(165, "洗礼是什么？", "洗礼是新约的圣礼，基督在其中命定奉父、子、圣灵的名用水施洗，作为<b>归入祂自己</b>、藉祂的血<b>赦罪</b>、藉祂的灵<b>重生</b>、<b>得儿子名分</b>并<b>复活得永生</b>的记号与印记；受洗者藉此被庄严地接纳进入<em>有形教会</em>，并公开宣认自己要全然且唯独属主。"),
   (166, "洗礼当施行给谁？", "不可施行给有形教会之外的人，直到他们宣认对基督的信心与顺服；<b>但父母双方或其中一方宣认信基督并顺服祂的，他们的婴孩就在这一点上是在约之内的，当受洗</b>。"),
   (167, "我们当如何善用自己的洗礼？", "这是一项<b>必需却被严重忽略</b>的本分，当终身履行，<em>尤其是在受试探时，以及在看见别人受洗时</em>：<br>——严肃而感恩地思想洗礼的性质、基督设立它的目的、藉它所授予并印证的特权与益处，以及我们在其中所立的庄严之约；<br>——为我们罪的污秽、为我们没有活出洗礼的恩典、反倒行事与之相违、辜负所立的约而<b>自卑</b>；<br>——<b>长进到确知罪得赦免</b>，以及那圣礼向我们印证的一切其他福分；<br>——从我们所归入之基督的死与复活中<b>汲取力量</b>，以治死罪、活化恩典；<br>——竭力凭信心而活，过圣洁公义的生活，如同已在其中把名字交给了基督的人；<b>并以弟兄之爱而行，因为我们都从一位圣灵受洗，归入了同一个身体</b>。")],
  core="问 167 是大要理最有原创性、也最有牧养力量的一问，在其他改革宗信条中<b>找不到对应</b>。它的洞见是：洗礼虽只施行一次，却要被<em>使用一生</em>。<b>「善用洗礼」（improving our baptism）不是重温仪式，而是把那个已经发生的印记，持续地应用到今天的试探、罪咎与软弱上。</b>",
  why="问 166 的婴孩洗礼针对当时迅速扩张的重洗派。论据是圣约的延续性：割礼之于旧约，如同洗礼之于新约（西2:11–12）；应许是「给你和你的儿女」（徒2:39）。<b>请注意措辞的精确</b>：婴孩受洗是因为他们「在这一点上是在约之内的」——这不等于说他们必然重生。洗礼印证的是约的应许，不是自动的救恩。",
  cont="海德堡问 74 论婴孩洗礼：「婴孩也当受洗吗？<b>当。因为他们与他们的父母同样属于神的约与祂的子民</b>；藉基督的血，赎罪与作成信心的圣灵，都同样应许给他们，如同应许给成人；因此他们也当藉着洗礼——就是约的记号——被接入基督教会，与不信者的儿女有别，正如旧约藉割礼所行的。」<br>而问 70 把洗礼的意义讲得极美：「被基督的血与灵洗净，就是……<em>被更新、被成圣为基督的肢体，以致越发向罪死、过圣洁无可指摘的生活</em>。」<b>但「善用洗礼」这一整套操练，是威敏独有的补充。</b>",
  view="问 167 的第二项——<b>为「没有活出洗礼的恩典」而自卑</b>——揭示了一个常被忽略的角度：洗礼不只是安慰，也是控诉。它是一个已经发生在我身上的、公开的、不可撤销的宣告；每一次我活得与它相违，那个印记就成了见证。",
  app="下次参加别人的洗礼时，按问 167 的六个动作做一遍：思想、自卑、长进到确据、汲取力量、凭信心而活、彼此相爱。<b>别人的洗礼是你重新使用自己洗礼的最好时机</b>——这正是问 167 明文指出的。",
  keys="太28:19　多3:5　加3:27　徒2:38–39　创17:7,9　林前7:14　西2:11–12　罗6:3–5　林前12:13　罗4:11–12"),

U("u39", "问168–171", "圣餐（上）：是什么，如何「吃」，如何预备",
  [(168, "主餐是什么？", "主餐是新约的圣礼；在其中按耶稣基督的指定授受饼与酒，<b>宣告祂的死</b>；凡按理领受的人，就<em>以祂的身体与血为食</em>，得属灵的滋养与恩典中的长进；他们与祂的联合与相通得着确认；他们的感恩、对神的委身，以及作为同一奥秘身体之肢体彼此的爱与团契，都得着见证与更新。"),
   (169, "基督如何指定饼与酒的授受？", "牧师当按基督的话拿起饼、擘开，并把饼与酒都递给领受者；领受者照同一指定，拿起、吃饼、喝酒，<b>怀着感恩的记念</b>——记念基督的身体为他们擘开、舍了，祂的血为他们流出。"),
   (170, "按理领受的人如何在主餐中以基督的身体与血为食？", "<b>基督的身体与血并非以形体或肉身的方式临在于饼酒之中、之下、或与之同在</b>；然而它们<em>属灵地临在于领受者的信心之前，其真实程度不亚于饼酒本身之临在于他们外在的感官</em>。因此，按理领受主餐的人，确实在其中以基督的身体与血为食——<b>不是以形体肉身的方式，乃是以属灵的方式；然而是真实的、实在的</b>——他们凭信心领受并把被钉的基督与祂受死的一切益处，应用在自己身上。"),
   (171, "领受主餐的人当如何预备自己？", "藉着<b>自我省察</b>：省察自己是否在基督里；省察自己的罪与缺乏；省察自己知识、信心、悔改的真实性与程度；省察自己对神与弟兄的爱、对众人的仁爱、是否饶恕了得罪自己的人；省察自己对基督的渴慕与新的顺服；<em>并藉着严肃的默想与恳切的祷告，重新操练这些恩典</em>。")],
  core="问 170 是整本大要理在措辞上最精密的一问，值得逐句拆开。它用<b>三个否定加三个肯定</b>定位改革宗的圣餐观：<br><em>否定</em>——不是形体的、不是肉身的、不在饼酒之中之下之同在。<br><em>肯定</em>——属灵地临在、临在于信心之前、真实而实在。<br>关键在那个类比：<b>基督临在于信心的真实程度，不亚于饼酒临在于感官的真实程度</b>。这一句既拒绝了实体临在，也拒绝了「只是象征」。",
  why="这一问同时对抗三方：<br><b>罗马教的变质说</b>（transsubstantiatio）——饼酒的实体变成基督的身体血；<br><b>路德宗的同在说</b>（饼酒之中、之下、与之同在，consubstantiatio 一类表述）；<br><b>茨温利式的纯纪念说</b>——圣餐只是记号，无真实的相通。<br>「不在……之中、之下、与之同在」（in, with, or under）这三个介词是刻意的，它们正是路德宗表述的标准用语。<em>威敏在这里明确地与路德宗分道。</em>",
  cont="<b>海德堡问 75–79 是改革宗圣餐论最著名的一段，与问 170 完全同调，但更温暖。</b><br>问 76 解释「吃基督被钉的身体、喝祂所流的血」是什么意思：「不但以信靠的心接受基督一切的苦难与死亡，藉此得赦罪与永生；<em>更是藉着那同时住在基督里、也住在我们里面的圣灵，与祂神圣的身体越发联合，以致我们虽然祂在天上、我们在地上，却仍是<b>祂骨中的骨、肉中的肉</b>。</em>」<br>问 78 明说饼酒「不变成基督真实的身体与血」；问 79 解释基督为何仍称饼为祂的身体——是为了教导，也是为了<b>用可见的记号与凭据向我们确证</b>。<br>而这段的前提正是海德堡问 47–48 的 <span class=\"lt\">extra Calvinisticum</span>：基督的人性在天上，神性不被人性所限；<em>所以联合不是把基督拉下来，而是圣灵把我们提上去</em>。<b>这一条是读懂问 170 的钥匙，威敏没有明写，欧陆写得很清楚。</b>",
  view="问 171 的自我省察清单常被误用为「够格才能来」的门槛。<b>这是严重的误读</b>——大要理自己在下一问（172）立刻纠正了这个误解。省察的目的不是评估资格，而是<em>重新操练恩典</em>（清单的最后一句）。省察若不通向渴慕与祷告，就走错了方向。",
  app="领餐前的预备，可以直接用问 171 的七项作为祷告的提纲。但请务必连着问 172 一起读——否则省察会变成自我定罪，而那恰恰是这个圣礼所要医治的。",
  keys="林前11:23–26　林前10:16–17　太26:26–28　林前11:28–29　约6:53–56　弗3:17　林前5:7–8"),

U("u40", "问172–175", "圣餐（下）：疑惑者、当被拦阻者，与领受前后",
  [(172, "疑惑自己是否在基督里、或疑惑自己预备是否得当的人，可以来领主餐吗？", "<b>疑惑自己是否在基督里的人，可能真的与基督有分，虽然他还没有得着确据</b>；在神的算计中他确实有分——只要他真为自己缺乏这确据而忧伤，并<em>真诚地渴望被发现在基督里、并脱离罪恶</em>。在这种情况下（因为应许正是为此而立的，这圣礼也正是为着<b>软弱与疑惑之基督徒的舒解</b>而设的），他当为自己的不信哀痛，努力解开疑惑；<b>这样行的人，他可以、并且应当来领主餐，好使自己更被坚固</b>。"),
   (173, "凡宣认信仰、愿意领主餐的人，有可以被拦阻的吗？", "凡被发现<b>在真道上无知、或行为上有公开的丑事</b>的，尽管他宣认信仰并愿意领受，<em>教会凭基督所留下的权柄，可以、并且应当拦阻他领受这圣礼，直到他受了教导、并显出悔改的实据为止</em>。"),
   (174, "领受主餐时，领受者当尽什么本分？", "以一切圣洁的敬畏与专注，在这典章中等候神；殷勤留意圣礼的元素与动作；<b>慎重地分辨主的身体</b>；深情地默想祂的死与受苦，藉此激动自己有力地操练各样恩典：<em>审判自己、为罪忧伤，恳切地渴慕基督如饥似渴，凭信心以祂为食，领受祂的丰盛，信靠祂的功劳，因祂的爱欢喜，为祂的恩感谢</em>；并更新自己与神所立的约，以及对众圣徒的爱。"),
   (175, "领受主餐之后，基督徒当尽什么本分？", "省察自己在其中的表现与果效。<b>若发现有生机与安慰</b>，就为此称颂神，恳求这恩得以持续，警惕故态复萌，履行所立的愿，并鼓励自己常常来领受这典章。<b>若当下并未发现益处</b>，就更仔细地检视自己领受前的预备与领受时的态度：若在这两方面都能在神与自己良心面前站立得住，<em>就当等候，果效必在合宜的时候显出</em>；若发现自己在某一方面失职，就当自卑，此后以更多的谨慎与殷勤来领受。")],
  core="问 172 是全篇最温柔的一问，也是最常被需要的一问。它给出一个几乎反直觉的判断：<b>「疑惑自己是否在基督里」这件事本身，若伴随着为此忧伤与真诚的渴慕，恰恰是有分于基督的凭据。</b>理由是：圣礼「<em>正是为着软弱与疑惑之基督徒的舒解而设的</em>」——软弱不是被拦阻的理由，而是来的理由。",
  why="十七世纪的长老会实行「围栏圣餐」（fencing the table），宣读警告以防不配领受。这一实践有圣经根据（林前11:27–29），却产生了一个牧养副作用：<b>最敏感的良心被吓退，最麻木的良心反倒安然领受</b>。问 172–173 的并置正是对这个副作用的精确校正——<em>拦阻的对象是「无知与公开的丑事」（问173），不是「疑惑与软弱」（问172）</em>。这两问必须一起读。",
  cont="海德堡问 81 给出同样的双重界定，措辞极为著名：「<b>谁当来到主的桌前？</b>就是那些真心为自己的罪忧伤、却信靠基督已为他们赎罪、其余的软弱已被祂的苦难与死亡遮盖、<em>并且渴望信心越发坚固、生命越发改正的人</em>。至于假冒为善与不悔改的人，则是吃喝自己的罪。」<br>问 82 随即处理拦阻：「凡以言行显明自己不信不敬的人，不可被接纳到主的桌前，<em>否则神的约就被亵渎，祂的忿怒就临到全会众</em>。因此按基督与祂使徒的规矩，基督的教会有责任用天国的钥匙把这些人拦阻，直到他们改正生活。」<b>海德堡问 81 的「渴望信心越发坚固」与威敏问 172 的「好使自己更被坚固」，是同一句话的两种说法。</b>",
  view="问 175 的后半段极有智慧：<b>领餐后没有感觉，不等于没有果效</b>。若预备与态度都经得起检视，那就「<em>等候，果效必在合宜的时候显出</em>」。这句话保护了信徒不把圣礼的价值建立在情绪经验上——同一个原则适用于读经、祷告与讲道。",
  app="若你曾因觉得自己不配而在领餐时退缩，问 172 就是写给你的。不配感本身不是拦阻；<b>无知与不悔改才是</b>。带着不配感来，正是这桌子设立的原因。",
  keys="赛50:10　诗88篇　林前11:27–29　太26:28　太5:23–24　林前5:11–13　太7:6　诗22:26　徒2:42,46　诗123:1–2"),

U("u41", "问176–177", "两礼的同与异",
  [(176, "洗礼与主餐在哪些方面相同？", "两者都由基督设立；都<b>表明并印证</b>祂中保之职的益处；都是<em>同一个约</em>的印记；都只可由福音的牧者施行，别人不可；并都要在基督的教会中持续，直到祂再来。"),
   (177, "两者在哪些方面不同？", "<b>洗礼</b>只施行一次，用水，作为我们重生并归入基督的记号与印记，<em>并且连婴孩也当受</em>；<b>主餐</b>则要常常施行，用饼与酒的元素，来表明并施予基督作为灵魂的属灵滋养，并确认我们在祂里面的持续与长进，<em>而且只施行给已到年岁、有能力自我省察的人</em>。")],
  core="这两问是一张精确的对照表。关键的不对称在最后：<b>洗礼可施于婴孩，主餐不可</b>。理由不是两者属于不同的约（问 176 明说是同一个约的印记），而是两个圣礼的<em>性质不同</em>——洗礼标记的是「被接纳进入」（一次性、被动地领受），主餐标记的是「持续地被喂养」（重复性、需要自我省察）。",
  why="这一区分回答了重洗派的一个常见质问：「既然婴孩可以受洗，为什么不能领餐？」大要理的回答不是权宜之计，而是从圣礼各自的记号内涵推出来的。<b>割礼施于八日的婴孩，逾越节却要求家长解释其意义（出12:26–27）</b>——旧约已经有同样的不对称。",
  cont="欧陆改革宗的实践与此完全一致：受洗的儿女在「公开宣认信仰」（belijdenis des geloofs）之前不领圣餐。海德堡问 81 的「真心为罪忧伤、信靠基督、渴望长进」三条，正是这个宣认所要查验的内容。<em>这一实践在两大谱系中是共同的</em>。",
  view="近几十年改革宗内部出现了「儿童领餐」（paedocommunion）的讨论，主张受洗的儿女也当领餐。这一主张在历史上的改革宗信条中<b>没有支持</b>（威敏问 177 与海德堡问 81 都明确要求自我省察的能力），但它在当代仍是一个被讨论的议题。诚实地说：<em>这是一个信条已有明文、而部分现代人提出异议的问题</em>，与前面几处「传统内合法分歧」的性质不同。",
  app="对有孩子的家庭，问 177 给出的不是排斥，而是一条清晰的路径：<b>孩子藉洗礼已属于约</b>（问166），他们此刻的任务是受教，直到能够省察自己、公开宣认，然后来到桌前。这个路径本身就是最好的教理教育动机。",
  keys="太28:19　林前11:23–26　罗4:11　西2:11–12　林前10:16　徒8:36–38　出12:26–27　林前11:28"),

U("u42", "问178–185", "祷告：定义、对象、名分、圣灵的帮助、内容与方式",
  [(178, "祷告是什么？", "祷告是<b>奉基督的名、藉祂圣灵的帮助，把我们的心愿献给神</b>；同时认自己的罪，并感恩地承认祂的怜悯。"),
   (179, "我们只可向神祷告吗？", "唯有神能鉴察人心、垂听祈求、赦免罪过、成全众人的心愿；也唯有祂当被信靠、当受宗教性的敬拜。祷告既是敬拜的一个特别部分，<b>就当由所有人单单向祂献上，不可向别的</b>。"),
   (180, "奉基督的名祷告是什么意思？", "是<em>出于顺服祂的命令、并信靠祂的应许</em>，为祂的缘故求怜悯；<b>不是单单提到祂的名字</b>，乃是从基督与祂的中保之职上，汲取我们祷告的勇气、胆量、力量与蒙悦纳的盼望。"),
   (181, "为什么要奉基督的名祷告？", "因为人的罪、以及由此而来与神的距离是如此之大，以致<b>若没有一位中保，我们根本无法进到祂面前</b>；天上地下也没有别人配作这中保的工作，唯有基督。"),
   (182, "圣灵如何帮助我们祷告？", "我们本不晓得当怎样祷告，圣灵就帮助我们的软弱：<b>使我们明白当为谁祷告、当求什么、当怎样求</b>；并在我们心里作成并激发那些正确履行此本分所必需的认识、情感与恩典（虽然不在每个人身上、也不在每个时候都是同样的分量）。"),
   (183, "我们当为谁祷告？", "为地上基督的全教会；为政府与牧者；为自己、为弟兄，<b>甚至为仇敌</b>；为各样活着的人，以及为将来要出生的人；<em>但不为死人，也不为那些已知犯了至于死之罪的人</em>。"),
   (184, "我们当为什么事祷告？", "为一切有助于<b>神的荣耀、教会的兴旺、自己与他人的益处</b>的事；<em>但不可为任何不合法的事祷告</em>。"),
   (185, "我们当如何祷告？", "带着对神威严的<b>敬畏</b>，并对自己的不配、缺乏与罪的深刻知觉；存悔改、感恩、宽广的心；带着<em>悟性、信心、真诚、恳切、爱心与恒心</em>，等候祂，并谦卑地顺服祂的旨意。")],
  core="问 178 的定义有四个要素，缺一不可：<b>把心愿献给神</b>（内容）、<b>奉基督的名</b>（根据）、<b>藉圣灵的帮助</b>（能力）、<b>认罪与感恩</b>（姿态）。整个定义是三一的——<em>向父，藉子，在灵里</em>。这不是修辞，是祷告的实际结构。",
  why="问 179 直接针对向圣徒与马利亚的祈求。论证方式是属性论的：<b>唯有那位能鉴察万人之心、同时垂听万人之求的，才可以被祷告</b>。任何受造者都不具备这种属性，因此向他们祷告在逻辑上就是把神的属性归给受造物——这落在第一诫之下（参问105）。",
  cont="海德堡问 116–119 论祷告。问 116 给出祷告为何必要的两个理由：「<b>因为祷告是神向我们所要的感恩中最重要的一部分；并且神唯独把祂的恩典与圣灵赐给那些恳切不住地向祂祈求、并为此感谢祂的人。</b>」——把祷告放在「感恩」的框架里，这是海德堡的特色。<br>问 117 列出蒙垂听祷告的三个条件，与威敏问 185 高度重合：<em>单单向那位在祂道中启示自己的独一真神祈求；彻底认识自己的需要与可怜，在祂威严面前自卑；确信祂必垂听我们，因为祂在道中如此应许了</em>。<b>第三条是海德堡的重音所在：确信不是祷告的奢侈品，是祷告的根据。</b>",
  view="问 183 的「<b>不为死人祷告</b>」是对炼狱说与代祷弥撒的直接否定（呼应问 86：灵魂死时立刻被成全或被定罪，无中间状态）。「<b>不为已知犯了至于死之罪的人祷告</b>」（约一5:16）则历来难解——改革宗主流的理解是它指向不可赦免的、终局性的悖逆，而且<em>我们几乎从不能确知某人落在其中</em>，因此这一条在实践上极少适用。切不可用它来停止为某人代祷。",
  app="问 182 是给「不会祷告」的人的：<b>不晓得当怎样祷告，正是圣灵介入的前提，不是祷告的障碍</b>（罗8:26）。而括号里那句「不在每个人身上、也不在每个时候都是同样的分量」，诚实地承认了祷告经验的起伏——这本身就是一种安慰。",
  keys="诗62:8　约16:23　罗8:26　但9:4　太4:10　约14:13–14　来4:14–16　弗6:18　提前2:1–2　太5:44　约一5:16　约一5:14　传5:1　雅1:6　弗6:18"),

U("u43", "问186–190", "主祷文：为何用它，它的结构，序言，第一求",
  [(186, "神为祷告的本分赐下了什么规则？", "整本圣经都有助于指导我们祷告；<b>但特别的规则，是我们的救主基督教导门徒的那个祷告样式，通称「主祷文」</b>。"),
   (187, "主祷文当如何使用？", "它不但是<b>指导的范本</b>——我们要照它的样式作别的祷告；<em>也可以当作祷告文本身来使用</em>，只要带着悟性、信心、敬畏，以及正确履行祷告所需的其他恩典。"),
   (188, "主祷文由几部分组成？", "三部分：<b>序言、祈求、结语</b>。"),
   (189, "主祷文的序言教导我们什么？", "「我们在天上的父」教导我们：祷告时当<b>确信祂父亲般的良善，也确信自己在其中有分</b>，从而坦然亲近祂；同时带着敬畏与一切为儿女者当有的心态、属天的情感，以及对祂至高权能、威严与<em>屈尊施恩</em>的正确认识；并且<b>要与别人一同祷告、也为别人祷告</b>。"),
   (190, "第一个祈求求什么？", "「愿人都尊你的名为圣」。我们先承认自己与众人<b>完全无能也不愿</b>正确地尊崇神；于是祈求神以祂的恩典，使我们与众人能够并乐意认识、承认、高举祂、祂的称号、属性、典章、圣道与作为，并在思想、言语、行为上荣耀祂；<em>又求祂以祂掌管一切的护理，安排万事，归祂自己的荣耀</em>。")],
  core="问 189 把「<b>我们在天上的</b>父」两个方向同时拉满：「父」给我们坦然亲近的胆量，「在天上」给我们敬畏的姿态。<b>只取一边，祷告就变形</b>——只取「父」变成随便，只取「在天上」变成惧怕。而那个「<em>我们</em>」则拆掉了祷告的私人性：主祷文从第一个字起就是复数的。",
  why="问 187 的措辞是一次刻意的平衡。当时的争论是：主祷文只是范本，还是可以逐字诵读？清教徒中激进的一派反对一切成文祷告（视为形式主义）。大要理的答案是<b>两者都可以</b>——只要不流于口舌。这在当时是一个温和而有分寸的立场。",
  cont="海德堡问 120–121 论序言，与此完全同调但更简：问 120 问「基督为何吩咐我们称神为『我们的父』？」答：「<b>要在我们祷告一开始，就在我们里面激起那当有的、像儿女对神的敬畏与信靠——这正是我们祷告的根基：神已经藉基督成为我们的父，我们凭信心向祂所求的，祂必不吝惜，正如我们的父母不肯拒绝我们地上的所需。</b>」<br>问 121 论「在天上」：「免得我们对神属天的威严存地上的想法，<em>并盼望从祂的全能中得着身体与灵魂一切的所需</em>。」",
  view="问 190 的开头值得注意：<b>每一个祈求都先从「承认我们自己无能」开始</b>。这是大要理解释主祷文的固定格式——第一求承认我们无力尊崇神，第二求承认我们在罪与撒但的权下，第三求承认我们既不能也不愿知道神的旨意，第四求承认我们已丧失对外在福分的权利，第五求承认我们都是神公义的欠债者，第六求承认我们随时可能被试探胜过。<em>六次承认，构成了主祷文的低音声部。</em>",
  app="问 189 末句「与别人一同祷告、也为别人祷告」提供了一个简单的检验：我的祷告里，第一人称单数与复数的比例是多少？主祷文全篇没有一个「我」。",
  keys="约一5:14　太6:9–13　路11:2–4　太7:9–11　徒12:5　诗67篇　诗145篇　罗11:36"),

U("u44", "问191–193", "第二、三、四求：国度、旨意、日用的饮食",
  [(191, "第二个祈求求什么？", "「愿你的国降临」。我们先承认自己与全人类<b>生来在罪与撒但的权下</b>；于是祈求：<em>罪与撒但的国被毁灭；福音传遍天下；犹太人被召；外邦人的数目添满</em>；教会得着一切福音的职分与典章，被洁净除去败坏，得着政府的支持与维护；基督的典章得以纯正地施行，并生效——使仍在罪中的人归正，使已归正的人得坚固、得安慰、被建立；<b>求基督如今就在我们心里作王，并催促祂再来的日子，使我们与祂一同永远作王</b>；并求祂在全世界如此运行祂权能的国，使这一切目的得以最好地成就。"),
   (192, "第三个祈求求什么？", "「愿你的旨意行在地上，如同行在天上」。我们先承认自己与众人<b>本性上不但完全不能、也不愿认识并遵行神的旨意，反倒倾向悖逆祂的话</b>、抱怨并厌恶祂的护理，全然倾向听从肉体与魔鬼的意思；于是祈求：神以祂的灵除去我们与他人心中一切的盲目、软弱、无心与刚愎；以祂的恩典使我们能够并乐意在万事上认识、遵行并顺服祂的旨意——<em>带着如同天上众天使那样的谦卑、喜乐、忠信、殷勤、热心、真诚与恒久</em>。"),
   (193, "第四个祈求求什么？", "「我们日用的饮食，今日赐给我们」。我们先承认<b>在亚当里、并因自己的罪，我们已丧失了享用今生一切外在福分的权利，理当被完全剥夺</b>，即便得着也当被咒诅；这些福分本身不能维持我们，我们也不配、也无力靠自己的努力得着；于是祈求：<em>我们与众人天天仰望神的护理，在使用合法手段的同时，凭祂白白的恩赐、照祂父亲般的智慧所认为最好的，得着一份够用的分</em>；并求这些福分得以持续、蒙祝福，使我们能圣洁而安然地使用，免于一切与之相违的事。")],
  core="这三求构成一个完整的下行：从<b>神的国</b>（宇宙性的）到<b>神的旨意</b>（道德性的）再到<b>今日的饮食</b>（物质性的）。次序本身是神学：<em>先求祂的国和祂的义，这些东西都要加给你们</em>（太6:33）。主祷文的结构就是这句话的展开。",
  why="问 191 中「<b>被政府支持与维护</b>」一语，反映的是威敏会议时期的政教格局（参第二部第六节论 1788 年修订）。在删改版的准则下，这一句通常被理解为「求政府保障教会自由地敬拜」，而不是求政府建立国教。<b>此处的处境差异，读者应当自行换算。</b>",
  cont="海德堡问 123 论第二求：「<b>愿你的国降临，就是：如此治理我们，使我们越发顺服你；保守并增长你的教会；毁灭魔鬼的作为与一切敌挡你的权势，以及一切抵挡你圣道的诡计；直到你国度的完全来临，那时你要在万有之中作王，作万有之主。</b>」<br>问 124 论第三求：「求你使我们与众人<em>舍弃自己的意思</em>，毫无怨言地顺从你那唯一良善的旨意；使各人都乐意忠心地履行自己的职分与呼召，<b>如同天上的天使一般</b>。」<br>问 125 论第四求：「求你供给我们身体一切的需用，好使我们藉此认识<em>你是一切美善的唯一源头</em>，也认识若没有你的祝福，我们的忧虑与劳碌、甚至你的恩赐，都对我们无益；<b>因此使我们把信靠从一切受造物挪开，单单放在你身上。</b>」<br><em>三处几乎逐点对应，海德堡更短、更第一人称，威敏更完整、更有教会论与宣教的维度。</em>",
  view="问 191 是整本大要理中<b>宣教心肠最明显</b>的一问：「福音传遍天下、犹太人被召、外邦人的数目添满」。请把它与问 60（未听闻福音者不能得救）并读——<em>那一问给出负担，这一问给出祷告</em>。有人批评改革宗的预定论会削弱宣教，问 191 是这项指控最直接的反证：<b>拣选的确定性正是祷告与差传的根据，不是它的替代品</b>。",
  app="问 193 的两个词值得记下：「<b>一份够用的分</b>」（a competent portion）与「<b>照祂父亲般的智慧所认为最好的</b>」。这两个限定语，把第四求从「求发财」拉回到「求够用」，并把决定权交回给父。",
  keys="弗2:2–3　诗68:1,18　帖后3:1　罗10:1　罗11:25　太9:38　启22:20　罗12:2　诗103:20–21　创28:20　提前4:4–5　箴30:8–9　太6:11,33"),

U("u45", "问194–196", "第五、六求与结语：赦免、保守、阿们",
  [(194, "第五个祈求求什么？", "「免我们的债，如同我们免了人的债」。我们先承认自己与众人<b>都有原罪与本罪，因而成了神公义的欠债者</b>，自己或任何受造物都无力偿还其中最小的一分；于是祈求：<em>神因祂白白的恩典，藉基督被信心支取并应用的顺服与补赎，赦免我们罪的刑罚与罪责，在祂的爱子里悦纳我们</em>；求祂对我们的恩宠与恩典得以持续，赦免我们每日的过失，以平安喜乐充满我们——就是天天赐下更多的赦免；<b>而当我们里面有这个凭据，就是我们从心里饶恕了别人的过犯时，我们就更放胆祈求，也更有把握盼望蒙应允</b>。"),
   (195, "第六个祈求求什么？", "「不叫我们遇见试探，救我们脱离凶恶」。我们先承认：那位至智、至义、至恩的神，为着许多圣洁公义的目的，可能如此安排，使我们遭受攻击、被击倒，甚至一时被试探掳去；撒但、世界与肉体随时有力地引诱我们；<b>而我们即使已经得赦，也仍因本性的败坏、警醒与努力的缺乏，不但会陷入试探，甚至会自己招引试探，无力抵挡、无力从中脱身</b>；于是祈求：神掌管世界与其中一切，制伏肉体，约束撒但，安排万事，赐下并祝福一切蒙恩之道，激动我们在使用它们时儆醒；<em>好使我们与祂一切的子民，藉祂的护理被保守不受试探；或者若受试探，藉祂的灵有力地被扶持，在试探的时刻站立得住；或者若已跌倒，被扶起、从网罗中被救回</em>；并使我们的成圣与救恩得以完全，<b>撒但被践踏在我们脚下，我们永远完全脱离罪、试探与一切的凶恶</b>。"),
   (196, "主祷文的结语教导我们什么？", "「因为国度、权柄、荣耀，全是你的，直到永远。阿们。」教导我们：<b>要用理由来加强我们的祈求；而这些理由不可取自我们自己或任何受造物的配得，唯独取自神</b>；并要在祈求之外加上赞美，把永恒的主权、全能与荣耀的卓越单单归给神。<em>正因祂既有能力、也有心意帮助我们，我们就凭信心放胆向祂恳求，并安然倚靠祂必成全我们的所求。</em>为要表明这份心愿与确据，我们就说——<b>阿们</b>。")],
  core="问 194 对「如同我们免了人的债」的处理极其精确：<b>饶恕别人不是蒙赦免的「条件」，而是我们已蒙赦免的「凭据」</b>（this testimony in ourselves）。这一个词的选择保住了唯独恩典——<em>若把它读成条件，整套称义论就崩了</em>；而它同时又保住了主耶稣那句话的分量（太6:14–15）。",
  why="问 195 承认了一个牧养上极重要的事实：<b>神可能安排我们「被击倒、甚至一时被试探掳去」</b>。这不是为跌倒开脱，而是防止跌倒的人得出「我从来就没得救」的绝望结论。彼得被筛，却有主为他祈求（路22:31–32）。这一问的三个层次——<em>不受试探／受试探时站立／跌倒后被扶起</em>——涵盖了每一种真实处境。",
  cont="海德堡问 126 论第五求：「<b>求你因基督的血，不将我们这些可怜罪人一切的过犯、以及仍然缠累我们的败坏归给我们；正如我们在自己里面找到你恩典的这个凭据：我们已经全心定意要饶恕我们的邻舍。</b>」——<em>「凭据」这个词在海德堡与威敏中完全一致</em>，两大谱系在这一点上的用词如出一辙。<br>问 127 论第六求；<b>问 128 论结语，给出一句比威敏更直接的理由</b>：「我们向你祈求这一切，是因为你作我们的王、掌管万有、也愿意并能够把一切美善赐给我们，<em>好叫你的圣名——而不是我们——因此得着荣耀</em>。」<br>问 129 论「阿们」：「<b>阿们的意思是：这是真的、确定的。因为神垂听我祷告的确实程度，远超过我心中所感受到的、我真在向祂祈求这件事。</b>」——<em>这是全本海德堡最后一句，也是它最动人的一句</em>：确据的根据不在我的感受，在神的信实。",
  view="问 196 的「<b>用理由来加强我们的祈求</b>」（enforce our petitions with arguments）是一种被现代人陌生化的祷告方式——圣经中的祷告者常常向神陈明理由（摩西、大卫、但以理都如此）。大要理的限定是：<em>理由不可取自我们的配得，只可取自神自己</em>——祂的国度、祂的权柄、祂的荣耀、祂的应许、祂的名。",
  app="全篇 196 问以「阿们」收束。按问 196，说「阿们」不是礼貌性的收尾，而是<b>一个信心的动作</b>：宣告「这是真的，祂必成就」。把海德堡问 129 一起记住，这两句合起来，是整套改革宗祷告论的句点。",
  keys="罗3:9–22　太18:35　弗1:6–7　路11:4　太6:14–15　太26:41　林后12:7–8　路22:31–32　罗16:20　但9:4,7–9,16–19　腓4:6　林后1:20"),
]
